import { EpicEntity, EpicStatus, ChangelogEntityType, ProjectEntity } from "./domain";
import { IndexedDbService } from "./indexed-db-service";
import { ChangelogLogic } from "./changelog-logic";
import { generateUUID, generateEpicId } from "./id-generation-logic";
import { calculateEpicProgress, deriveStatus } from "./progress-calculation-logic";
import { StoryLogic } from "./story-logic";

export const EpicLogic = (
  indexedDbService,
  changelogLogic,
  idGenerationLogic,
  progressCalculationLogic,
  storyLogic
) => {
  const ENTITY_TYPE = 'epics';
  const PROJECT_ENTITY_TYPE = 'projects';
  const STORY_ENTITY_TYPE = 'stories';

  const createEpic = async (projectId, data) => {
    const now = new Date().toISOString();

    const project = await indexedDbService.getEntity(PROJECT_ENTITY_TYPE, projectId);
    if (!project) {
      throw new Error(`Invalid projectId: ${projectId}. Project does not exist.`);
    }

    const id = idGenerationLogic.generateUUID();
    const code = await idGenerationLogic.generateEpicId(projectId);

    const newEpic = EpicEntity({
      ...data,
      id,
      projectId,
      code,
      isBlocked: false,
      createdAt: now,
      updatedAt: now,
      status: EpicStatus.NOT_STARTED,
    });

    await indexedDbService.addEntity(ENTITY_TYPE, newEpic);

    await changelogLogic.recordChange(
      ChangelogEntityType.EPIC,
      newEpic.id,
      newEpic.code,
      "entity_status",
      "CREATED",
      EpicStatus.NOT_STARTED
    );

    return newEpic;
  };

  const getEpic = async (id) => {
    const epic = await indexedDbService.getEntity(ENTITY_TYPE, id);
    if (!epic) {
      return undefined;
    }

    const stories = await storyLogic.getStoriesByEpic(epic.id);
    const progress = progressCalculationLogic.calculateEpicProgress(stories);
    const derivedStatus = progressCalculationLogic.deriveStatus(progress, epic.isBlocked);

    return { ...epic, status: derivedStatus };
  };

  const getEpicsByProject = async (projectId) => {
    const allEpics = await indexedDbService.getEntities(ENTITY_TYPE);
    const projectEpics = allEpics.filter(epic => epic.projectId === projectId);

    const enrichedEpics = await Promise.all(projectEpics.map(async (epic) => {
      const stories = await storyLogic.getStoriesByEpic(epic.id);
      const progress = progressCalculationLogic.calculateEpicProgress(stories);
      const derivedStatus = progressCalculationLogic.deriveStatus(progress, epic.isBlocked);
      return { ...epic, status: derivedStatus };
    }));

    return enrichedEpics;
  };

  const updateEpic = async (id, data) => {
    const now = new Date().toISOString();
    const originalEpic = await indexedDbService.getEntity(ENTITY_TYPE, id);

    if (!originalEpic) {
      throw new Error(`Epic with ID ${id} not found.`);
    }

    const updatedEpic = EpicEntity({ ...originalEpic, ...data, updatedAt: now });

    for (const field in data) {
      if (Object.prototype.hasOwnProperty.call(data, field) && data[field] !== originalEpic[field]) {
        await changelogLogic.recordChange(
          ChangelogEntityType.EPIC,
          id,
          originalEpic.code,
          field,
          String(originalEpic[field]),
          String(data[field])
        );
      }
    }

    if (data.isBlocked !== undefined && data.isBlocked !== originalEpic.isBlocked) {
      const stories = await storyLogic.getStoriesByEpic(updatedEpic.id);
      const progress = progressCalculationLogic.calculateEpicProgress(stories);
      const newStatus = progressCalculationLogic.deriveStatus(progress, updatedEpic.isBlocked);

      if (newStatus !== originalEpic.status) {
        await changelogLogic.recordChange(
          ChangelogEntityType.EPIC,
          id,
          originalEpic.code,
          "status",
          originalEpic.status,
          newStatus
        );
      }
      updatedEpic.status = newStatus;
    } else {
      // If isBlocked is not changed, but other fields might affect status (e.g., if stories are updated elsewhere)
      // Re-derive status based on current stories and potentially new isBlocked state (if it was updated)
      const stories = await storyLogic.getStoriesByEpic(updatedEpic.id);
      const progress = progressCalculationLogic.calculateEpicProgress(stories);
      const newStatus = progressCalculationLogic.deriveStatus(progress, updatedEpic.isBlocked);
      if (newStatus !== originalEpic.status) {
        await changelogLogic.recordChange(
          ChangelogEntityType.EPIC,
          id,
          originalEpic.code,
          "status",
          originalEpic.status,
          newStatus
        );
        updatedEpic.status = newStatus;
      }
    }

    await indexedDbService.updateEntity(ENTITY_TYPE, id, updatedEpic);
    return updatedEpic;
  };

  const deleteEpic = async (id) => {
    const epic = await indexedDbService.getEntity(ENTITY_TYPE, id);
    if (!epic) {
      return; // Resolve without action if epic not found
    }

    const stories = await storyLogic.getStoriesByEpic(id);
    await Promise.all(stories.map(story => storyLogic.deleteStory(story.id)));

    await changelogLogic.recordDeletion(
      ChangelogEntityType.EPIC,
      id,
      epic.code
    );

    await indexedDbService.deleteEntity(ENTITY_TYPE, id);
  };

  return {
    createEpic,
    getEpic,
    getEpicsByProject,
    updateEpic,
    deleteEpic,
  };
};